{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2174-09-19 21:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I understand you've been having abdominal pain for the past three days?"
    },
    {
      "turn_number": 2,
      "time": "2174-09-19 21:16:00",
      "speaker": "Patient",
      "text": "Yes, it started while I was visiting my son. It’s sharp and right around my feeding tube."
    },
    {
      "turn_number": 3,
      "time": "2174-09-19 21:17:00",
      "speaker": "Doctor",
      "text": "I see. Is the pain constant? Does anything make it better or worse?"
    },
    {
      "turn_number": 4,
      "time": "2174-09-19 21:18:00",
      "speaker": "Patient",
      "text": "It’s constant and sharp. It gets worse when I eat solids or when the tube feeds are running."
    },
    {
      "turn_number": 5,
      "time": "2174-09-19 21:19:00",
      "speaker": "Doctor",
      "text": "And you’ve had no fever, vomiting, or changes in bowel movements?"
    },
    {
      "turn_number": 6,
      "time": "2174-09-19 21:20:00",
      "speaker": "Patient",
      "text": "No, I’ve been passing gas and having normal bowel movements. No redness or drainage at the tube site."
    },
    {
      "turn_number": 7,
      "time": "2174-09-19 21:21:00",
      "speaker": "Doctor",
      "text": "Okay. Given your history, we’ll start with some blood work and a chest X-ray to rule out infection or other issues."
    },
    {
      "turn_number": 8,
      "time": "2174-09-19 21:22:00",
      "speaker": "Patient",
      "text": "Will I need to stop my tube feeds?"
    },
    {
      "turn_number": 9,
      "time": "2174-09-19 21:23:00",
      "speaker": "Doctor",
      "text": "We’ll hold them for now to see if that helps your pain. But we’ll give you IV fluids with dextrose to prevent low blood sugar."
    },
    {
      "turn_number": 10,
      "time": "2174-09-19 21:24:00",
      "speaker": "Patient",
      "text": "That makes sense. I do get shaky if my sugar drops."
    },
    {
      "turn_number": 11,
      "time": "2174-09-20 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs came back normal—no signs of infection or organ issues. The chest X-ray was clear too."
    },
    {
      "turn_number": 12,
      "time": "2174-09-20 08:01:00",
      "speaker": "Patient",
      "text": "That’s a relief. So what’s causing the pain?"
    },
    {
      "turn_number": 13,
      "time": "2174-09-20 08:02:00",
      "speaker": "Doctor",
      "text": "It seems related to your tube site and possibly your stomach lining. We’ll keep you NPO for now and continue IV dextrose."
    },
    {
      "turn_number": 14,
      "time": "2174-09-20 08:03:00",
      "speaker": "Patient",
      "text": "How long will I need to stay like this?"
    },
    {
      "turn_number": 15,
      "time": "2174-09-20 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll reassess in a day or two. If your pain improves, we’ll try small oral intake."
    },
    {
      "turn_number": 16,
      "time": "2174-09-21 09:00:00",
      "speaker": "Doctor",
      "text": "Your pain seems a bit better today. We’re going to start weaning off the IV dextrose slowly."
    },
    {
      "turn_number": 17,
      "time": "2174-09-21 09:01:00",
      "speaker": "Patient",
      "text": "That’s good. Can I try eating something small?"
    },
    {
      "turn_number": 18,
      "time": "2174-09-21 09:02:00",
      "speaker": "Doctor",
      "text": "We’ll start with sips of water and light snacks. We’ll monitor your blood sugar every four hours."
    },
    {
      "turn_number": 19,
      "time": "2174-09-21 09:03:00",
      "speaker": "Patient",
      "text": "Okay, I’ll try. I’m worried I won’t get enough calories."
    },
    {
      "turn_number": 20,
      "time": "2174-09-21 09:04:00",
      "speaker": "Doctor",
      "text": "We’re tracking your intake. If it’s too low, we may add a medication to help with appetite."
    },
    {
      "turn_number": 21,
      "time": "2174-09-22 10:00:00",
      "speaker": "Doctor",
      "text": "Your blood sugars are stable in the low 100s. But your oral intake is still below target—about 60% of your needs."
    },
    {
      "turn_number": 22,
      "time": "2174-09-22 10:01:00",
      "speaker": "Patient",
      "text": "I’m just not very hungry. Everything feels full."
    },
    {
      "turn_number": 23,
      "time": "2174-09-22 10:02:00",
      "speaker": "Doctor",
      "text": "We’re going to start Marinol, a medication that can help stimulate your appetite. It’s often used in cases like yours."
    },
    {
      "turn_number": 24,
      "time": "2174-09-22 10:03:00",
      "speaker": "Patient",
      "text": "Is that like medical marijuana?"
    },
    {
      "turn_number": 25,
      "time": "2174-09-22 10:04:00",
      "speaker": "Doctor",
      "text": "It’s a synthetic form that helps with appetite without strong psychoactive effects. We’ll start low."
    },
    {
      "turn_number": 26,
      "time": "2174-09-23 11:00:00",
      "speaker": "Doctor",
      "text": "Great news—your intake improved yesterday. You hit about 85% of your calorie goal."
    },
    {
      "turn_number": 27,
      "time": "2174-09-23 11:01:00",
      "speaker": "Patient",
      "text": "I did feel a bit hungrier. Is that the Marinol?"
    },
    {
      "turn_number": 28,
      "time": "2174-09-23 11:02:00",
      "speaker": "Doctor",
      "text": "Likely so. We’ll keep it going. We’re also arranging a dietitian consult to help plan your meals after discharge."
    },
    {
      "turn_number": 29,
      "time": "2174-09-23 11:03:00",
      "speaker": "Patient",
      "text": "That would be helpful. I always worry about my sugar dropping."
    },
    {
      "turn_number": 30,
      "time": "2174-09-23 11:04:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll give you specific instructions on small, frequent meals with protein and low-glycemic carbs."
    },
    {
      "turn_number": 31,
      "time": "2174-09-24 08:30:00",
      "speaker": "Doctor",
      "text": "You’ve been pain-free for two days now. We’re going to restart your tube feeds at a low rate to see how you tolerate it."
    },
    {
      "turn_number": 32,
      "time": "2174-09-24 08:31:00",
      "speaker": "Patient",
      "text": "Will that bring the pain back?"
    },
    {
      "turn_number": 33,
      "time": "2174-09-24 08:32:00",
      "speaker": "Doctor",
      "text": "We’ll go slowly. If pain returns, we’ll stop again. But the goal is to see if you can eventually stop the tube altogether."
    },
    {
      "turn_number": 34,
      "time": "2174-09-24 08:33:00",
      "speaker": "Patient",
      "text": "Really? I could stop the tube?"
    },
    {
      "turn_number": 35,
      "time": "2174-09-24 08:34:00",
      "speaker": "Doctor",
      "text": "Yes, that’s the long-term plan—over several months. If you can maintain nutrition by mouth and stay pain-free."
    },
    {
      "turn_number": 36,
      "time": "2174-09-25 09:15:00",
      "speaker": "Doctor",
      "text": "You tolerated the low-rate tube feeds well overnight. No pain or discomfort?"
    },
    {
      "turn_number": 37,
      "time": "2174-09-25 09:16:00",
      "speaker": "Patient",
      "text": "No, I didn’t feel anything. That’s a good sign, right?"
    },
    {
      "turn_number": 38,
      "time": "2174-09-25 09:17:00",
      "speaker": "Doctor",
      "text": "Very good. We’ll continue to increase the rate gradually and monitor you."
    },
    {
      "turn_number": 39,
      "time": "2174-09-26 10:00:00",
      "speaker": "Doctor",
      "text": "The dietitian met with you yesterday. How did that go?"
    },
    {
      "turn_number": 40,
      "time": "2174-09-26 10:01:00",
      "speaker": "Patient",
      "text": "Really helpful. She gave me a meal plan and tips for snacking safely."
    },
    {
      "turn_number": 41,
      "time": "2174-09-26 10:02:00",
      "speaker": "Doctor",
      "text": "Perfect. You’ll follow up with her as an outpatient too."
    },
    {
      "turn_number": 42,
      "time": "2174-09-27 08:45:00",
      "speaker": "Doctor",
      "text": "We’re planning your discharge for early next week. You’re doing well—pain-free and eating well."
    },
    {
      "turn_number": 43,
      "time": "2174-09-27 08:46:00",
      "speaker": "Patient",
      "text": "That’s great. Will I still need the tube at home?"
    },
    {
      "turn_number": 44,
      "time": "2174-09-27 08:47:00",
      "speaker": "Doctor",
      "text": "Yes, for now. But we’ll follow up in a few weeks to reassess. The goal is to remove it eventually."
    },
    {
      "turn_number": 45,
      "time": "2174-09-28 09:00:00",
      "speaker": "Doctor",
      "text": "Your blood work is stable, and you’ve maintained over 90% of your calorie needs orally."
    },
    {
      "turn_number": 46,
      "time": "2174-09-28 09:01:00",
      "speaker": "Patient",
      "text": "I’ve been sticking to the dietitian’s plan. I feel more in control."
    },
    {
      "turn_number": 47,
      "time": "2174-09-28 09:02:00",
      "speaker": "Doctor",
      "text": "That’s exactly what we want to hear. We’ll keep your pain meds and stomach medications the same for now."
    },
    {
      "turn_number": 48,
      "time": "2174-09-29 10:30:00",
      "speaker": "Doctor",
      "text": "We’re scheduling your follow-up with Dr. Patel in four weeks. They’ll help monitor your progress."
    },
    {
      "turn_number": 49,
      "time": "2174-09-29 10:31:00",
      "speaker": "Patient",
      "text": "And the dietitian too?"
    },
    {
      "turn_number": 50,
      "time": "2174-09-29 10:32:00",
      "speaker": "Doctor",
      "text": "Yes, you’ll see them first. They’ll adjust your plan based on how you’re doing."
    },
    {
      "turn_number": 51,
      "time": "2174-09-30 08:00:00",
      "speaker": "Doctor",
      "text": "One more day and we’ll discharge you tomorrow morning if all goes well."
    },
    {
      "turn_number": 52,
      "time": "2174-09-30 08:01:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. But what if the pain comes back?"
    },
    {
      "turn_number": 53,
      "time": "2174-09-30 08:02:00",
      "speaker": "Doctor",
      "text": "Call us. We’ll want to know. But keep taking your medications and stick to the diet."
    },
    {
      "turn_number": 54,
      "time": "2174-10-01 09:00:00",
      "speaker": "Doctor",
      "text": "All set for discharge today. You’re afebrile, pain-free, and eating well."
    },
    {
      "turn_number": 55,
      "time": "2174-10-01 09:01:00",
      "speaker": "Patient",
      "text": "What about my blood sugar monitoring?"
    },
    {
      "turn_number": 56,
      "time": "2174-10-01 09:02:00",
      "speaker": "Doctor",
      "text": "Check it before meals and at bedtime. And wear the Dexcom monitor we discussed to track trends."
    },
    {
      "turn_number": 57,
      "time": "2174-10-01 09:03:00",
      "speaker": "Patient",
      "text": "I’ll do that. And take my meds as prescribed."
    },
    {
      "turn_number": 58,
      "time": "2174-10-01 09:04:00",
      "speaker": "Doctor",
      "text": "Exactly. We’ll see you in follow-up, and we’ll decide then about the tube."
    },
    {
      "turn_number": 59,
      "time": "2174-10-03 12:00:00",
      "speaker": "Doctor",
      "text": "Just a quick visit—we’re documenting that you received your final tube feeding before discharge."
    },
    {
      "turn_number": 60,
      "time": "2174-10-03 12:01:00",
      "speaker": "Patient",
      "text": "It went fine. No pain at all."
    },
    {
      "turn_number": 61,
      "time": "2174-10-04 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re officially discharged. Keep up the great work."
    },
    {
      "turn_number": 62,
      "time": "2174-10-04 07:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel so much better."
    },
    {
      "turn_number": 63,
      "time": "2174-10-04 07:02:00",
      "speaker": "Doctor",
      "text": "We’re glad. Call if anything changes. Take care."
    },
    {
      "turn_number": 64,
      "time": "2174-10-04 07:03:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    }
  ],
  "summary": {
    "admission_start": "2174-09-19 21:01:00",
    "admission_end": "2174-10-04 13:17:00",
    "summary_paragraph": "The patient was admitted for abdominal pain localized around her gastrostomy tube site, worsening over three days. She has a complex history including prior gastric bypass and reversal, post-surgical hypoglycemia, and multiple prior admissions for similar pain. Management was conservative: tube feeds were held and IV dextrose was given to prevent hypoglycemia. Pain improved with this approach. Oral intake was initially poor, so Marinol was started, which significantly improved caloric intake to 90% of goal. The patient tolerated gradual reintroduction of tube feeds without pain recurrence. She was discharged home after 15 days, pain-free and stable, with a plan to follow up with her surgeon and dietitian. The long-term goal is to discontinue tube feeds if oral intake remains adequate and symptoms do not return.",
    "problems": [
      "Epigastric pain",
      "Nausea with vomiting, unspecified",
      "Gastrostomy status",
      "Major depressive disorder, single episode, unspecified",
      "Dehydration",
      "Hypoglycemia, unspecified",
      "Obstructive sleep apnea (adult) (pediatric)",
      "Gastro-esophageal reflux disease without esophagitis",
      "Anxiety disorder, unspecified",
      "Hyperlipidemia, unspecified",
      "Bariatric surgery status"
    ]
  }
}
